package cn.kejian;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.net.Uri;import android.Manifest;import android.content.pm.PackageManager;import java.time.*;
public final class Reminders extends BroadcastReceiver {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("reminders",0);}
 public static void enable(Activity a,boolean on){prefs(a).edit().putBoolean("enabled",on).apply();if(on&&Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},22);return;}AlarmManager m=a.getSystemService(AlarmManager.class);if(on&&Build.VERSION.SDK_INT>=31&&!m.canScheduleExactAlarms()){try{a.startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+a.getPackageName())));}catch(android.content.ActivityNotFoundException ignored){}};schedule(a);}
 private static final java.util.concurrent.ExecutorService WORK=java.util.concurrent.Executors.newSingleThreadExecutor();
 public static void schedule(Context context){Context app=context.getApplicationContext();WORK.execute(()->{try{LiveCourseNotification.refresh(app,new ScheduleRepository(app));scheduleNow(app);}catch(Exception ignored){}});}
 private static void scheduleNow(Context c){AlarmManager alarms=c.getSystemService(AlarmManager.class);for(int i=0;i<100;i++){PendingIntent p=PendingIntent.getBroadcast(c,5000+i,new Intent(c,Reminders.class).setAction("course"),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){alarms.cancel(p);p.cancel();}}if(!prefs(c).getBoolean("enabled",false))return;ScheduleRepository repo=new ScheduleRepository(c);long now=System.currentTimeMillis();int i=0;for(java.util.Map.Entry<Long,java.util.List<ScheduleLogic.Course>> group:ReminderPlan.groups(repo.courses,prefs(c).getInt("minutes",15),now).entrySet()){if(i>=100)break;long time=group.getKey();String names=String.join(" / ",group.getValue().stream().map(course->course.name).toArray(String[]::new));String info=String.join("\n",group.getValue().stream().map(course->course.name+" · "+course.time()+(course.room.isEmpty()?"":" · "+course.room)).toArray(String[]::new));Intent in=new Intent(c,Reminders.class).setAction("course").putExtra("name",names).putExtra("info",info).putExtra("notificationId",(int)(time^(time>>>32)));PendingIntent p=PendingIntent.getBroadcast(c,5000+i++,in,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT<31||alarms.canScheduleExactAlarms())alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time,p);else alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time,p);}}

 @Override public void onReceive(Context c,Intent i){if("course".equals(i.getAction())&&prefs(c).getBoolean("enabled",false)){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("courses","课程提醒",NotificationManager.IMPORTANCE_HIGH));PendingIntent tap=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(c,"courses").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(i.getStringExtra("name")).setContentText(i.getStringExtra("info")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("info"))).setContentIntent(tap).setAutoCancel(true).build();if(Build.VERSION.SDK_INT<33||c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)n.notify(i.getIntExtra("notificationId",1),notification);}final PendingResult pending=goAsync();WORK.execute(()->{try{Context app=c.getApplicationContext();LiveCourseNotification.refresh(app,new ScheduleRepository(app));if(!LiveCourseNotification.ACTION.equals(i.getAction()))scheduleNow(app);}catch(Exception ignored){}finally{pending.finish();}});}
}
